def topo_sort(graph):
    from collections import defaultdict

    graph = dict(graph)
    nodes = set()
    adj = defaultdict(list)

    for src, dests in graph.items():
        nodes.add(src)
        for dst in dests:
            nodes.add(dst)
            adj[src].append(dst)

    for src in nodes:
        adj[src] = sorted(set(adj[src]))

    WHITE, GRAY, BLACK = 0, 1, 2
    color = {n: WHITE for n in nodes}
    result = []

    def dfs(node):
        color[node] = GRAY
        for neighbor in adj[node]:
            if color[neighbor] == GRAY:
                raise ValueError("Döngü tespit edildi")
            if color[neighbor] == WHITE:
                dfs(neighbor)
        color[node] = BLACK
        result.append(node)

    for node in sorted(nodes):
        if color[node] == WHITE:
            dfs(node)

    result.reverse()
    return result
