def topo_sort(graph):
    from collections import defaultdict

    # Tüm düğümleri topla (kaynaklar + hedefler)
    nodes = set(graph.keys())
    for targets in graph.values():
        nodes.update(targets)

    indegree = {node: 0 for node in nodes}
    adjacency = defaultdict(list)

    for src, targets in graph.items():
        seen = set()
        for dst in targets:
            if dst in seen:
                continue  # aynı kenarın tekrarını yoksay
            seen.add(dst)
            adjacency[src].append(dst)
            indegree[dst] += 1

    # Leksikografik en küçük sıralama için min-heap
    import heapq
    heap = [node for node in nodes if indegree[node] == 0]
    heapq.heapify(heap)

    result = []
    while heap:
        node = heapq.heappop(heap)
        result.append(node)
        for neighbor in adjacency[node]:
            indegree[neighbor] -= 1
            if indegree[neighbor] == 0:
                heapq.heappush(heap, neighbor)

    if len(result) != len(nodes):
        raise ValueError("Döngü tespit edildi: topolojik sıralama mümkün değil.")

    return result
